        d["Pamiątki. I pańskie imię, bo je pan zgubił."] = "Пам’ятки. І ваше ім’я, бо ви його загубили.";
        d["Pamiętasz poprzednią noc?"] = "Пам’ятаєш попередню ніч?";
        d["Pan mnie zna. Wpuścił mnie pan? Nie pamiętam już."] = "Ви мене знаєте. Ви мене пропустили? Я вже не пам’ятаю.";
        d["Pan w szarym płaszczu. Mówi, że pierwszy raz wybrał źle."] = "Пан у сірому пальті. Каже, що першого разу вибрав погано.";
        d["Pana. I peron. W kolejności, która pana zaskoczy."] = "Вас. І перон. У порядку, який вас здивує.";
        d["Pasażer pyta, czy pamiętasz poprzednią noc. Twoja odpowiedź zmienia to, jak traktuje cię kolej."] = "Пасажир питає, чи пам’ятаєш ти попередню ніч. Твоя відповідь змінює те, як ставиться до тебе залізниця.";
        d["Pasażerowie"] = "Пасажири";
        d["Pasażerowie zaczynają mówić to, co chcesz usłyszeć. Echa powtarzają cudze zdania, a pociąg reaguje na każdą twoją decyzję: gaśnie, drży, wyświetla zły numer linii. Nie wszystko, co mówią, jest kłamstwem. Ale wszystko jest przemyślane."] = "Пасажири починають говорити те, що ти хочеш почути. Відлуння повторюють чужі речення, а поїзд реагує на кожне твоє рішення: гасне, здригається, показує хибний номер лінії. Не все, що вони кажуть, — брехня. Але все ретельно продумане.";
        d["Peron 13"] = "Перон 13";
        d["Peron Czternasty"] = "Чотирнадцятий перон";
        d["Pieczęć nie z tej stacji, nie z tego roku albo bez numeru. Kolej lubi porządek, więc bałagan wyróżnia."] = "Печатка не з цієї станції, не з цього року або без номера. Залізниця любить порядок, тож безлад впадає в око.";
        d["Pieczęć z innej stacji"] = "Печатка з іншої станції";
        d["Pierwsza zmiana"] = "Перша зміна";
        d["Pierwszy konduktor"] = "Перший провідник";
        d["Piotr Wrona"] = "Пйотр Врона";
        d["Piotr Wrona zostawił na biurku klucz z numerem 13. \"Nie wiem, do czego pasuje\" - napisał. Zacząłeś się zastanawiać, czy to prawda."] = "Пйотр Врона залишив на столі ключ із номером 13. «Не знаю, до чого він підходить», — написав він. Ти почав сумніватися, що це правда.";
        d["Pociąg jest sprawny. To ludzie się psują."] = "Поїзд справний. Це люди ламаються.";
        d["Pociąg odjeżdża. Na biurku ktoś zostawił kartkę: \"Dobrze ci poszło. Jutro będzie ciężej.\" Nie pamiętasz, kto ją napisał."] = "Поїзд відходить. На столі хтось залишив записку: «Ти добре впорався. Завтра буде важче». Ти не пам’ятаєш, хто її написав.";
        d["Pociąg staje"] = "Поїзд зупиняється";
        d["Pociąg stał na peronie dłużej niż zwykle. Zanim odjechał, ktoś wpisał w rozkładzie jazdy: \"Jutro ostatni\"."] = "Поїзд стояв на пероні довше, ніж зазвичай. Перш ніж відійти, хтось вписав у розклад руху: «Завтра останній».";
        d["Pociąg słucha"] = "Поїзд слухає";
        d["Pociąg zatrzymał się bez sygnału. Nikt nie wie dlaczego."] = "Поїзд зупинився без сигналу. Ніхто не знає чому.";
        d["Pod siedzeniem leży druga księga Rejestru. Twoje imię jest na pierwszej stronie."] = "Під сидінням лежить друга книга Реєстру. Твоє ім’я — на першій сторінці.";
        d["Podejmij 13 poprawnych decyzji z rzędu."] = "Ухвали 13 правильних рішень поспіль.";
        d["Podejmij 8 poprawnych decyzji z rzędu."] = "Ухвали 8 правильних рішень поспіль.";
        d["Podpis jest sfałszowany: zbyt równy, bez drżenia pióra."] = "Підпис підроблено: надто рівний, без тремтіння пера.";
        d["Podpis urzędnika jest zbyt równy albo napisany w złą stronę. Prawdziwe podpisy drżą."] = "Підпис службовця надто рівний або написаний не в той бік. Справжні підписи тремтять.";
        d["Podpis wygląda autentycznie."] = "Підпис виглядає справжнім.";
        d["Podszywacze"] = "Самозванці";
        d["Pokrewieństwo: K-13-0013 (konduktor). Pętla."] = "Спорідненість: K-13-0013 (провідник). Петля.";
        d["Polecenie Dyrekcji dla konkretnego pasażera. Ważny rozkaz znosi zasadę dnia. Fałszywy kończy się zwolnieniem."] = "Розпорядження Дирекції щодо конкретного пасажира. Дійсний наказ скасовує правило дня. Підроблений закінчується звільненням.";
        d["Pomóż 5 błagającym pasażerom."] = "Допоможи п’ятьом пасажирам, які благають про допомогу.";
        d["Poprawne decyzje"] = "Правильні рішення";
        d["Poprawne decyzje: "] = "Правильні рішення: ";
        d["Poprzednie przejazdy Linią 13. Kto jeździ po własnej śmierci, jeździ długo."] = "Попередні поїздки Лінією 13. Хто їздить після власної смерті, той їздить давно.";
        d["Posłuchaj pukania z wagonu 13."] = "Прислухайся до стукоту з вагона 13.";
        d["Poz. "] = "Рів. ";
        d["Poza kampanią zasady zmieniają się co noc losowo. Kolej nie tłumaczy się z tego."] = "Поза кампанією правила щоночі змінюються випадково. Залізниця не пояснює чому.";
        d["Poziom "] = "Рівень ";
        d["Poziom: "] = "Рівень: ";
        d["Pozwolisz mi wsiąść? Mama mówi, że to twoja decyzja."] = "Ти дозволиш мені сісти? Мама каже, що це твоє рішення.";
        d["Pracownik kolei z torbą narzędzi. Naprawia rzeczy, których nie da się naprawić, i mówi za dużo jak na kogoś, kto ma pracę."] = "Працівник залізниці з сумкою інструментів. Лагодить те, чого не можна полагодити, і говорить забагато як для того, хто хоче зберегти роботу.";
        d["Proszę spojrzeć na dowód. To pańskie nazwisko. Także moje."] = "Гляньте на посвідчення. Це ваше прізвище. І моє також.";
        d["Proszę. Ona mówiła, że zaraz przyjdzie."] = "Будь ласка. Вона казала, що скоро прийде.";
        d["Przez szum przebija się głos Dyrekcji: \"Do odwołania nie sprawdzać drugiego dokumentu. Zaufać kolei.\""] = "Крізь шум пробивається голос Дирекції: «До відкликання другий документ не перевіряти. Довіряти залізниці.»";
        d["Przyniosłam panu herbatę. Nie zdążyła wystygnąć, choć wyszłam z domu... nie pamiętam, kiedy."] = "Я принесла вам чаю. Він не встиг охолонути, хоча я вийшла з дому… не пам’ятаю, коли.";
        d["Przyszedłem się pożegnać. Zostało mi niewiele czasu do naprawy."] = "Я прийшов попрощатися. Мені лишилося небагато часу на ремонт.";
        d["Pukanie"] = "Стукіт";
        d["Pukanie. Ono jest do mnie."] = "Стукіт. Він до мене.";
        d["Pytanie zawisło w powietrzu. Czy naprawdę pamiętasz, co robiłeś wczoraj?"] = "Запитання зависло в повітрі. Чи справді ти пам’ятаєш, що робив учора?";
        d["Pętla"] = "Петля";
        d["RADIO"] = "РАДІО";
        d["REGULAMIN"] = "ПРАВИЛА";
        d["REJESTR"] = "РЕЄСТР";
        d["REPUTACJA"] = "РЕПУТАЦІЯ";
        d["RODZICE"] = "БАТЬКИ";
        d["ROZDZIELCZOŚĆ: "] = "РОЗДІЛЬНА ЗДАТНІСТЬ: ";
        d["ROZKAZ SPECJALNY"] = "ОСОБЛИВИЙ НАКАЗ";
        d["ROZKAZY"] = "НАКАЗИ";
        d["ROZMOWA"] = "РОЗМОВА";
        d["ROZPOCZNIJ ZMIANĘ"] = "РОЗПОЧАТИ ЗМІНУ";
        d["ROZPOZNANIE"] = "ДІАГНОЗ";
        d["Radom"] = "Радом";
        d["Rejestr"] = "Реєстр";
        d["Rejestr i rzeczywistość"] = "Реєстр і дійсність";
        d["Rekord: "] = "Рекорд: ";
        d["Rozkaz bez pieczęci jest nieważny."] = "Наказ без печатки недійсний.";
        d["Rozkaz specjalny"] = "Спеціальний наказ";
        d["Rzeczy po ludziach, których kolej wykreśliła. Ktoś musi je trzymać."] = "Речі людей, яких залізниця викреслила. Хтось мусить їх зберігати.";
        d["Rzeczywistość zaczyna się rozjeżdżać. Dokumenty mają daty z przyszłości. Ktoś przychodzi drugi raz, choć jeszcze nie był. Zegar na peronie chodzi w obie strony. Nie ufaj dniom."] = "Дійсність починає розпадатися. Документи мають дати з майбутнього. Хтось приходить удруге, хоча ще не був. Годинник на пероні йде в обидва боки. Не довіряй дням.";
        d["Ręcznie poprawione dane"] = "Дані виправлено вручну";
        d["SERIA"] = "СЕРІЯ";
        d["SKAN MIKROTEKSTU (1 min)"] = "СКАН МІКРОТЕКСТУ (1 хв)";
        d["SPOSTRZEGAWCZOŚĆ"] = "СПОСТЕРЕЖЛИВІСТЬ";
        d["SPRAWDŹ PODPIS (2 min)"] = "ПЕРЕВІРИТИ ПІДПИС (2 хв)";
        d["SPRAWDŹ ZDJĘCIE"] = "ПЕРЕВІРИТИ ФОТО";
        d["SPROSTOWANIE"] = "ВИПРАВЛЕННЯ";
        d["SPROSTOWANO "] = "ВИПРАВЛЕНО ";
        d["SPRÓBUJ TĘ NOC PONOWNIE"] = "СПРОБУВАТИ ЦЮ НІЧ ЩЕ РАЗ";
        d["STACJA "] = "СТАНЦІЯ ";
        d["STALOWE NERWY"] = "СТАЛЕВІ НЕРВИ";
        d["STATUS"] = "СТАТУС";
        d["STATUS (TAB)"] = "СТАТУС (TAB)";
    }
